/* Вставка схем в карточки. Работает без правок index.html:
   схема добавляется в блок «Схема постановки» после отрисовки сетки. */
(function () {
  function install() {
    var grid = document.getElementById("grid");
    if (!grid || typeof renderMap !== "function") return;
    function apply() {
      grid.querySelectorAll(".card").forEach(function (card) {
        var d = DRILLS.filter(function (x) { return x.n === card.getAttribute("data-n"); })[0];
        if (!d || !d.map) return;
        var secs = card.querySelectorAll(".sec");
        for (var i = 0; i < secs.length; i++) {
          var h = secs[i].querySelector("h4");
          if (h && h.textContent.indexOf("Схема постановки") === 0) {
            if (!secs[i].querySelector(".mapsvg")) {
              try { secs[i].insertAdjacentHTML("beforeend", renderMap(d.map)); } catch (e) {}
            }
            return;
          }
        }
      });
    }
    apply();
    new MutationObserver(apply).observe(grid, { childList: true });
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", install);
  else install();
})();
